$guid = "AB83D231-8C12-9413-FEBA-C0F9888B9290"

if ( Get-CMDuplicateHardwareIdGuid -Id $guid ) {
  Write-Host $guid "exists in the site"
} else {
  Write-Host $guid "doesn't exist!"
}

$mac = "01:23:45:67:89:AB"

if ( Get-CMDuplicateHardwareIdMacAddress -Id $mac ) {
  Write-Host $mac "exists in the site"
} else {
  Write-Host $mac "doesn't exist!"
}

$app617 = Get-CMApplication -ApplicationName "LOB app v6.17"
$lockUser = ($app617 | Get-CMObjectLockDetails).AssignedUser

if ( $lockUser -eq "" ) {
  Set-CMApplication -InputObject $app617 -NewName "Central app v6.17"
} else {
  Write-Warning "There's a SEDO lock on app $($app617.LocalizedDisplayName)"
}

$og = Get-CMOrchestrationGroup -Name "IT servers"

foreach ( $member in $og.MOGMembers ) {
  Get-CMDevice -Id $member -Fast | Select-Object Name, Build
}

$og = Get-CMOrchestrationGroup -Name "IT servers"

$devices = @()
foreach ( $id in $og.MOGMembers ) {
  $devices += Get-CMDevice -Id $id -Fast
}

$sortedIDs = ( $devices | Sort-Object -Property Name | Select-Object ResourceId ).ResourceId

$parameters = @{
  InputObject = $og
  Description = "Change type and sequence"
  OrchestrationType = "Sequence"
  MemberResourceIds = $sortedIDs
}

Set-CMOrchestrationGroup @parameters

$ts = Get-CMTaskSequence -Name "Default IPU"

$tscondition = New-CMTSStepConditionVariable -ConditionVariableName "_SMSTSInWinPE" -ConditionVariableValue "false" -OperatorType Equals

$tsrule1 = New-CMTSRule -DefaultGateway "192.168.10.1" -Variable @{'OSDRegisteredUserName' = 'Contoso';'OSDRegisteredOrgName' = 'Contoso'}
$tsrule2 = New-CMTSRule -Make "Surface" -Model "*" -Variable @{'custTattoo1' = 'AllSurface'}

$ts | Set-CMTaskSequenceStepSetDynamicVariable -ClearCondition -AddCondition $tscondition -CleanRule -AddRule ($tsrule1,$tsrule2)
